function formatBookingTime(value:unknown,timeZone?:string){if(!value)return 'No appointment time';try{return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short',...(timeZone?{timeZone}:{})}).format(new Date(String(value)))}catch{return new Date(String(value)).toLocaleString()}}
