type ManifestShift='morning'|'afternoon'|'night'
const localDateKey=(value:Date|string)=>{const date=value instanceof Date?value:new Date(value);if(Number.isNaN(date.getTime()))return '';return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
