const shiftForHour=(hour:number):ManifestShift=>hour<12?'morning':hour<17?'afternoon':'night'
const minutesToLabel=(minutes:number)=>{const hour=Math.floor(minutes/60),minute=minutes%60;return new Date(2020,0,1,hour,minute).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}
const initials=(name:string)=>String(name||'Guest').split(/\s+/).slice(0,2).map(part=>part[0]).join('').toUpperCase()

